-- Theory display IDs are category-local. The stable row IDs and all
-- technique-to-theory relationships remain unchanged.
drop index if exists public.theories_published_display_id_uidx;
drop index if exists public.theories_draft_display_id_uidx;
create unique index theories_published_category_display_id_uidx
  on public.theories(category_id,display_id) where status='published';
create unique index theories_draft_category_display_id_uidx
  on public.theories(category_id,draft_display_id) where status='draft';

create or replace function public.reorder_content(target_kind text,target_scope text,target_ids text[])
returns void language plpgsql security definer set search_path=''
as $$
declare
  actual_count integer;
  item_category text;
begin
  if not public.is_owner() then raise exception 'owner_required' using errcode='42501'; end if;
  if target_ids is null or cardinality(target_ids)=0 or cardinality(target_ids)<>(select count(distinct v) from unnest(target_ids) v)
    or array_position(target_ids,null) is not null then
    raise exception '順序に重複または空のIDがあります。' using errcode='22023';
  end if;

  if target_kind in ('technique-category','theory-category') then
    item_category:=split_part(target_kind,'-',1);
    perform pg_advisory_xact_lock(hashtextextended('category:'||item_category,0));
    select count(*) into actual_count from public.content_categories
      where kind=item_category and id=any(target_ids);
    if actual_count<>cardinality(target_ids) or actual_count<>(select count(*) from public.content_categories where kind=item_category) then
      raise exception 'カテゴリの範囲が一致しません。' using errcode='22023';
    end if;
    update public.content_categories set display_order=-display_order where kind=item_category;
    update public.content_categories set display_order=array_position(target_ids,id),updated_at=now() where kind=item_category;
  elsif target_kind='persona' then
    perform pg_advisory_xact_lock(hashtextextended('persona:'||target_scope,0));
    select count(*) into actual_count from public.personas
      where category=target_scope and status<>'archived' and id=any(target_ids);
    if actual_count<>cardinality(target_ids) or actual_count<>(select count(*) from public.personas where category=target_scope and status<>'archived') then
      raise exception '人物像の範囲が一致しません。' using errcode='22023';
    end if;
    update public.personas set display_order=-display_order where category=target_scope and status<>'archived';
    update public.personas set display_order=array_position(target_ids,id),updated_at=now() where id=any(target_ids);
  elsif target_kind='technique' then
    perform pg_advisory_xact_lock(hashtextextended('technique:'||target_scope,0));
    select count(*) into actual_count from public.techniques
      where persona_id=target_scope and status='published' and id=any(target_ids);
    if actual_count<>cardinality(target_ids) or actual_count<>(select count(*) from public.techniques where persona_id=target_scope and status='published') then
      raise exception '処世術の範囲が一致しません。' using errcode='22023';
    end if;
    update public.techniques set display_order=-display_order where persona_id=target_scope and status='published';
    update public.techniques set display_order=array_position(target_ids,id),updated_at=now() where id=any(target_ids);
  elsif target_kind='theory' then
    if nullif(target_scope,'') is null then raise exception '理論カテゴリを指定してください。' using errcode='22023'; end if;
    perform pg_advisory_xact_lock(hashtextextended('theory-display-id',0));
    select count(*) into actual_count from public.theories
      where status='published' and category_id=target_scope and id=any(target_ids);
    if actual_count<>cardinality(target_ids)
      or actual_count<>(select count(*) from public.theories where status='published' and category_id=target_scope) then
      raise exception '理論カテゴリの一覧が一致しません。' using errcode='22023';
    end if;
    update public.theories set display_id=-display_id
      where status='published' and category_id=target_scope;
    update public.theories set display_id=array_position(target_ids,id),updated_at=now()
      where status='published' and category_id=target_scope;
  else
    raise exception '順序の対象が不正です。' using errcode='22023';
  end if;
end;
$$;
revoke all on function public.reorder_content(text,text,text[]) from public;
grant execute on function public.reorder_content(text,text,text[]) to authenticated;

-- Draft order is also dense and local to one category. The supplied IDs must
-- be the complete draft list for the category they belong to.
create or replace function public.reorder_theory_drafts(target_ids text[])
returns void language plpgsql security definer set search_path=''
as $$
declare
  target_category text;
  actual_count integer;
begin
  if not public.is_owner() then raise exception 'owner_required' using errcode='42501'; end if;
  if target_ids is null or cardinality(target_ids)=0 then return; end if;
  if cardinality(target_ids)<> (select count(distinct v) from unnest(target_ids) v)
    or array_position(target_ids,null) is not null then
    raise exception '下書き理論の順序に重複または空のIDがあります。' using errcode='22023';
  end if;
  select category_id into target_category from public.theories where id=target_ids[1] and status='draft';
  if target_category is null then raise exception '下書き理論が見つかりません。' using errcode='P0002'; end if;
  select count(*) into actual_count from public.theories
    where status='draft' and category_id=target_category and id=any(target_ids);
  if actual_count<>cardinality(target_ids)
    or actual_count<>(select count(*) from public.theories where status='draft' and category_id=target_category) then
    raise exception '下書き理論カテゴリの範囲が一致しません。' using errcode='22023';
  end if;
  update public.theories set draft_display_id=-draft_display_id
    where status='draft' and category_id=target_category;
  update public.theories set draft_display_id=array_position(target_ids,id),updated_at=now()
    where status='draft' and category_id=target_category;
end;
$$;
revoke all on function public.reorder_theory_drafts(text[]) from public;

create or replace function public.move_theory_display_id(target_theory_id text,target_display_id integer,target_status text,target_category_id text default null)
returns public.theories language plpgsql security definer set search_path=''
as $$
declare
  item public.theories;
  source_category text;
  destination_category text;
  source_ids text[]:='{}'::text[];
  destination_ids text[]:='{}'::text[];
  source_draft_ids text[]:='{}'::text[];
  destination_draft_ids text[]:='{}'::text[];
  next_ids text[]:='{}'::text[];
  next_draft_ids text[]:='{}'::text[];
  destination_count integer;
  draft_destination_count integer;
  requested integer;
begin
  if not public.is_owner() then raise exception 'owner_required' using errcode='42501'; end if;
  if target_status not in ('draft','published') then raise exception '公開状態が不正です。' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('theory-display-id',0));
  select * into item from public.theories where id=target_theory_id for update;
  if not found then raise exception 'theory_not_found' using errcode='P0002'; end if;
  source_category:=item.category_id;
  destination_category:=coalesce(target_category_id,source_category);
  if not exists(select 1 from public.content_categories where kind='theory' and id=destination_category) then
    raise exception '理論カテゴリを選択してください。' using errcode='23503';
  end if;

  if item.status='published' then
    select coalesce(array_agg(id order by display_id),'{}'::text[]) into source_ids
      from public.theories where status='published' and category_id=source_category and id<>target_theory_id;
  end if;
  if destination_category=source_category and item.status='published' then
    destination_ids:=source_ids;
  else
    select coalesce(array_agg(id order by display_id),'{}'::text[]) into destination_ids
      from public.theories where status='published' and category_id=destination_category and id<>target_theory_id;
  end if;
  if item.status='draft' then
    select coalesce(array_agg(id order by draft_display_id),'{}'::text[]) into source_draft_ids
      from public.theories where status='draft' and category_id=source_category and id<>target_theory_id;
  end if;
  if destination_category=source_category and item.status='draft' then
    destination_draft_ids:=source_draft_ids;
  else
    select coalesce(array_agg(id order by draft_display_id),'{}'::text[]) into destination_draft_ids
      from public.theories where status='draft' and category_id=destination_category and id<>target_theory_id;
  end if;

  if target_status='draft' then
    draft_destination_count:=cardinality(destination_draft_ids);
    requested:=greatest(1,least(coalesce(target_display_id,item.draft_display_id,item.display_id,draft_destination_count+1),draft_destination_count+1));
    next_draft_ids:=destination_draft_ids[1:requested-1]||array[target_theory_id]||destination_draft_ids[requested:draft_destination_count];
    update public.theories set status='draft',display_id=null,display_order=null,
      draft_display_id=-2147483647,category_id=destination_category,
      category_title=(select title from public.content_categories where kind='theory' and id=destination_category),
      updated_at=now(),updated_by=auth.uid()
    where id=target_theory_id;
    if item.status='published' and cardinality(source_ids)>0 then
      perform public.reorder_content('theory',source_category,source_ids);
    elsif item.status='draft' and source_category<>destination_category and cardinality(source_draft_ids)>0 then
      perform public.reorder_theory_drafts(source_draft_ids);
    end if;
    perform public.reorder_theory_drafts(next_draft_ids);
  else
    destination_count:=cardinality(destination_ids);
    requested:=greatest(1,least(coalesce(target_display_id,item.draft_display_id,item.display_id,destination_count+1),destination_count+1));
    next_ids:=destination_ids[1:requested-1]||array[target_theory_id]||destination_ids[requested:destination_count];
    update public.theories set display_id=-display_id
      where status='published' and category_id in (source_category,destination_category);
    update public.theories set status='published',display_id=-2147483647,draft_display_id=null,
      category_id=destination_category,
      category_title=(select title from public.content_categories where kind='theory' and id=destination_category),
      updated_at=now(),updated_by=auth.uid()
    where id=target_theory_id;
    if item.status='published' and source_category<>destination_category and cardinality(source_ids)>0 then
      perform public.reorder_content('theory',source_category,source_ids);
    elsif item.status='draft' and cardinality(source_draft_ids)>0 then
      perform public.reorder_theory_drafts(source_draft_ids);
    end if;
    perform public.reorder_content('theory',destination_category,next_ids);
  end if;
  select * into item from public.theories where id=target_theory_id;
  return item;
end;
$$;
revoke all on function public.move_theory_display_id(text,integer,text,text) from public;
grant execute on function public.move_theory_display_id(text,integer,text,text) to authenticated;

create or replace function public.create_theory_draft(target_category_id text)
returns public.theories language plpgsql security definer set search_path=''
as $$
declare result public.theories; new_id text;
begin
  if not public.is_owner() then raise exception 'owner_required' using errcode='42501'; end if;
  if not exists(select 1 from public.content_categories where kind='theory' and id=target_category_id) then
    raise exception '理論カテゴリを選択してください。' using errcode='23503'; end if;
  perform pg_advisory_xact_lock(hashtextextended('theory-display-id',0));
  new_id:='theory-'||gen_random_uuid()::text;
  insert into public.theories(id,title,summary,category_id,category_title,aliases,related_theory_ids,status,display_order,display_id,draft_display_id,updated_by)
  values(new_id,'','',target_category_id,(select title from public.content_categories where kind='theory' and id=target_category_id),
    '[]'::jsonb,'[]'::jsonb,'draft',null,null,
    (select count(*)+1 from public.theories where status='draft' and category_id=target_category_id),auth.uid())
  returning * into result;
  return result;
end;
$$;
revoke all on function public.create_theory_draft(text) from public;
grant execute on function public.create_theory_draft(text) to authenticated;

create or replace function public.publish_theory(target_theory_id text,payload jsonb)
returns public.theories language plpgsql security definer set search_path=''
as $$
declare result public.theories;
begin
  if not public.is_owner() then raise exception 'owner_required' using errcode='42501'; end if;
  if nullif(trim(payload->>'title'),'') is null or nullif(trim(payload->>'summary'),'') is null then
    raise exception 'タイトルと概要を入力してください。' using errcode='22023'; end if;
  if not exists(select 1 from public.content_categories where kind='theory' and id=payload->>'category_id') then
    raise exception '理論カテゴリを選択してください。' using errcode='23503'; end if;
  -- Keep the old category until the sequence helper has captured its source
  -- list; it applies the new category atomically with the publish transition.
  update public.theories set title=trim(payload->>'title'),summary=trim(payload->>'summary'),
    aliases=coalesce(payload->'aliases','[]'::jsonb),related_theory_ids=coalesce(payload->'related_theory_ids','[]'::jsonb),
    provenance=case when payload ? 'provenance' then nullif(payload->'provenance','null'::jsonb) else provenance end,
    image_path=case when payload ? 'image_path' then payload->>'image_path' else image_path end,
    access_tier=coalesce(payload->>'access_tier',access_tier),draft_technique_ids='[]'::jsonb,
    updated_at=now(),updated_by=auth.uid()
  where id=target_theory_id returning * into result;
  if not found then raise exception 'theory_not_found' using errcode='P0002'; end if;
  perform public.move_theory_display_id(target_theory_id,
    coalesce((payload->>'display_id')::integer,(payload->>'draft_display_id')::integer,(payload->>'display_order')::integer),
    'published',payload->>'category_id');
  select * into result from public.theories where id=target_theory_id;
  if payload ? 'related_technique_ids' then
    perform public.set_theory_techniques(result.id,array(select jsonb_array_elements_text(payload->'related_technique_ids')));
  end if;
  return result;
end;
$$;
revoke all on function public.publish_theory(text,jsonb) from public;
grant execute on function public.publish_theory(text,jsonb) to authenticated;

create or replace function public.archive_theory(target_theory_id text)
returns public.theories language plpgsql security definer set search_path=''
as $$
declare
  result public.theories;
  item public.theories;
  ids text[]:='{}'::text[];
  draft_ids text[]:='{}'::text[];
begin
  if not public.is_owner() then raise exception 'owner_required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('theory-display-id',0));
  select * into item from public.theories where id=target_theory_id for update;
  if not found then raise exception 'theory_not_found' using errcode='P0002'; end if;
  if item.status='published' then
    select coalesce(array_agg(id order by display_id),'{}'::text[]) into ids
      from public.theories where status='published' and category_id=item.category_id and id<>target_theory_id;
  elsif item.status='draft' then
    select coalesce(array_agg(id order by draft_display_id),'{}'::text[]) into draft_ids
      from public.theories where status='draft' and category_id=item.category_id and id<>target_theory_id;
  end if;
  update public.theories set status='archived',display_id=null,display_order=null,draft_display_id=null,
    updated_at=now(),updated_by=auth.uid() where id=target_theory_id returning * into result;
  if item.status='published' and cardinality(ids)>0 then perform public.reorder_content('theory',item.category_id,ids); end if;
  if item.status='draft' and cardinality(draft_ids)>0 then perform public.reorder_theory_drafts(draft_ids); end if;
  return result;
end;
$$;
revoke all on function public.archive_theory(text) from public;
grant execute on function public.archive_theory(text) to authenticated;

